using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MilitaryOwnHeadAuthorityTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static void Send(WorldSession s,NewMilitaryAction a,bool renewal=false){var i=new NewMilitaryInput(new("request:own-head/"+s.Revision+"/"+a),a){AuthorityPolicy=a==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null,CycleContract=renewal?NewGameMilitary.RenewalContract:null};var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
 static void Pickup(WorldSession s){Send(s,NewMilitaryAction.Request);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Pickup);}
 [Theory][InlineData("person:nobunaga")][InlineData("person:shingen")][InlineData("person:ujiyasu")]
 public void HistoricalHeadCanExplicitlyPrepareHouseMilitaryWithoutSelfService(string id){var s=NewGameWorldTests.Session([],id);var w=s.DiagnosticSnapshot();Assert.True(NewGameMilitary.ViewWithAuthority(w).CanRequest);Assert.Empty(w.Units);Assert.DoesNotContain(w.ServiceBonds,b=>b.Subject==s.PlayerControl);Pickup(s);w=s.DiagnosticSnapshot();var g=Assert.Single(w.NewMilitary!.Authority!.Grants);Assert.Equal(s.PlayerControl,w.NewMilitary.Terms.Principal);Assert.Equal(s.PlayerControl,g.Mandate.Agent);Assert.DoesNotContain(w.ServiceBonds,b=>b.Subject==s.PlayerControl&&b.Target==s.PlayerControl);Assert.All(w.Units,u=>Assert.Equal(g.Owner,u.Organization));Assert.NotEqual(s.PlayerControl,g.Owner);new WorldSession(w);}
 [Fact]public void CreatedHeadUsesNewHouseAndRestoresSameReturnAndReappointment(){var p=NewGameWorldTests.Officer(role:StartTemplate.Daimyo);var setup=NewGameWorldTests.Setup([p],[new(p.Id,"org:own-head-test",[p.Site],true)]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,p.Id));Pickup(s);var other=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,other}){Send(v,NewMilitaryAction.Report);At(v,v.Seconds+1);Send(v,NewMilitaryAction.Return);At(v,v.Seconds+2);Open(v);}Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(other.DiagnosticSnapshot()));var old=Assert.Single(s.DiagnosticSnapshot().NewMilitary!.Authority!.Grants);foreach(var v in new[]{s,other}){var view=NewGameMilitary.ViewWithAuthority(v.DiagnosticSnapshot());Assert.True(view.CanRequest,view.Status+" / events="+string.Join(",",v.DiagnosticSnapshot().NewMilitary!.Events.Select(e=>e.Effect))+" / openings="+v.DiagnosticSnapshot().NewMilitary!.Openings.Length);Send(v,NewMilitaryAction.Request,true);At(v,v.Seconds+2);Open(v);Send(v,NewMilitaryAction.Accept);At(v,v.Seconds+2);Open(v);Send(v,NewMilitaryAction.Pickup);}var w=s.DiagnosticSnapshot();Assert.Equal(2,w.NewMilitary!.Authority!.Grants.Length);var current=w.NewMilitary.Authority.Grants.Last();Assert.NotEqual(old.Case,current.Case);Assert.False(NewGameMilitary.ScopedAuthorityAllows(old,current.Case,s.PlayerControl,current.Mandate.Army,current.Mandate.Units[0],RegionalAction.Move,s.Seconds,s.Revision));Assert.All(w.NewMilitary.Authority.Grants,g=>Assert.Equal(new EntityId("org:own-head-test"),g.Owner));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(other.DiagnosticSnapshot()));}
 [Fact]public void LegacyHeadRequestDoesNotSilentlyOptIntoOwnAuthority(){var s=NewGameWorldTests.Session([],"person:shingen");var w=s.DiagnosticSnapshot();string hash=ContractJson.CanonicalHash(w);Assert.False(NewGameMilitary.View(w).CanRequest);Assert.True(NewGameMilitary.ViewWithAuthority(w).CanRequest);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(new(new("request:legacy-head"),NewMilitaryAction.Request),s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void RoninAndOrdinaryRetainerCannotClaimHeadPath(){foreach(var p in new[]{NewGameWorldTests.Officer(),NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")}){var s=NewGameWorldTests.Session([p]);Assert.False(NewGameMilitary.CanRequestOwnAuthority(s.DiagnosticSnapshot()));}}
 [Fact]public void OwnHeadFieldReturnIsInternalIntentAndCompletesAfterPhysicalArmyAndStockReturn(){var s=NewGameWorldTests.Session([],"person:shingen");Pickup(s);var load=new NewMilitaryInput(new("request:own-head-field-load"),NewMilitaryAction.Load,100000);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(load,s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());var form=new NewMilitaryInput(new("request:own-head-field-form"),NewMilitaryAction.Form,0,new(a.X+20000,a.Y-12000),new(a.X+20000,a.Y+12000));Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(form,s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Return);var w=s.DiagnosticSnapshot();var message=w.NewMilitary!.Requests.Last(q=>q.Input.Action==NewMilitaryAction.Return).Message!;At(s,s.Seconds+1);w=s.DiagnosticSnapshot();Assert.True(NewGameMilitary.HandlesInternalAuthorityMessage(w,message));Assert.True(HakutaiKagami.Core.Messaging.MessageFlow.Knows(w.Messaging,message,s.PlayerControl.Value));Assert.DoesNotContain(w.Couriers!.Missions,c=>w.Messaging.Attempts.Single(x=>x.Id==c.Attempt).MessageId==message);Assert.DoesNotContain(w.NewMilitary!.Events,e=>e.Effect==MilitaryEffect.Returned);var other=new WorldSession(w);foreach(var v in new[]{s,other}){Send(v,NewMilitaryAction.Recall);At(v,v.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(v,NewMilitaryAction.Enter);var amount=NewGameMilitary.View(v.DiagnosticSnapshot()).Carry;Assert.Equal(ResultCode.Accepted,v.DecideNewMilitary(new(new("request:own-head-field-unload"),NewMilitaryAction.Unload,amount),v.PlayerControl,v.Revision).Code);Send(v,NewMilitaryAction.Report);At(v,v.Seconds+2);Open(v);}w=s.DiagnosticSnapshot();Assert.Contains(w.NewMilitary!.Events,e=>e.Effect==MilitaryEffect.Returned);Assert.NotNull(w.NewMilitary.Authority!.Grants.Single().UntilRevision);Assert.Contains("指揮返還を確認",NewGameMilitary.AuthorityKnownStatus(w));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(other.DiagnosticSnapshot()));}
}
